def set_assets_path(path):
    """Retarget active project assets without changing the unsaved defaults."""
    global ASSETS_PATH
    ASSETS_PATH = path
    for name, folder in _asset_folders.items():
        globals()[name] = os.path.join(path, folder)


def configure_asset_defaults(path):
    """Apply the startup preference, falling back if it cannot be used."""
    path = os.path.abspath(os.path.expanduser(path or USER_PATH))
    try:
        _check_assets_folder(path)
        for folder in _asset_folders.values():
            _check_assets_folder(os.path.join(path, folder))
    except OSError:
        path = USER_PATH
        for folder in _asset_folders.values():
            os.makedirs(os.path.join(path, folder), exist_ok=True)
    set_assets_path(path)
    for name in ("ASSETS_PATH", *_asset_folders):
        _path_defaults[name] = globals()[name]
    return path

def get_app():
    """ Get the current QApplication instance of OpenShot """
    return QApplication.instance()

class PathUtilsTests(unittest.TestCase):
    def test_windows_drive_paths_are_treated_as_local_paths(self):
        path = r"C:\Projects\example_assets\title\intro.svg"

        self.assertEqual(normalized_local_path(path), os.path.normpath(os.path.abspath(path)))
        self.assertEqual(comparable_local_path(path), os.path.normcase(os.path.normpath(os.path.abspath(path))))

    def test_content_uris_remain_opaque(self):
        path = "content://documents/tree/project.osp"

        self.assertEqual(normalized_local_path(path), path)
